-- insert-cartagena-centers.sql
-- Inserta los 17 centros de educacion infantil (0-3 anos) del termino
-- municipal de Cartagena (casco urbano + pedanias con vida administrativa
-- propia) investigados y humanizados en este sprint: 11 escuela-infantil
-- (Escuelas Infantiles Municipales del Ayuntamiento de Cartagena, publico)
-- + 6 guarderia (privados).
-- Fuente: data/enrichment/cartagena-centers.json (generado 2026-07-12).
-- Fuentes primarias de datos: (1) API oficial mapaescolar-api de la
-- Comunidad Autonoma de la Region de Murcia (CARM), dataset "Sedes de los
-- Centros Educativos de la Region de Murcia" (datosabiertos.regiondemurcia.es);
-- (2) educacion.cartagena.es (Concejalia de Educacion, Ayuntamiento de
-- Cartagena), fuente principal para las 11 Escuelas Infantiles Municipales
-- (horario, servicios, edad minima real de 4 meses, gratuidad); (3) webs
-- oficiales de 2 centros privados verificados individualmente (Nice Day,
-- Mediterraneo Cartagena). Ver docs/data-sources-cartagena.md.
--
-- Ninguna fuente disponible incluye distritos formales del casco urbano de
-- Cartagena, por lo que district queda NULL en los 17 centros;
-- neighborhood_barrio recoge el barrio/pedania cuando la fuente lo indica
-- con claridad. Pozo Estrecho queda sin coordenadas (latitude/longitude
-- NULL) por no haber podido geocodificar la direccion exacta con precision
-- suficiente; La Aljorra usa una aproximacion a nivel de calle via
-- Nominatim/OpenStreetMap, documentada en el dataset de origen.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por
-- RLS hasta cambiarlos a 'published' manualmente, igual que se hizo con
-- Madrid, Barcelona, Valencia y Murcia).
-- No toca ningun centro de Madrid, Barcelona, Valencia, Murcia ni ninguna
-- otra ciudad ya integrada. No borra ni modifica filas existentes (upsert
-- por slug: si un slug ya existe se actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar. NO EJECUTADO por el
-- agente que lo genero.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "cartagena" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('cartagena', 'Cartagena', 'Murcia', 'Región de Murcia')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('eim-barrio-peral-cartagena', 'Escuela Infantil Municipal Barrio Peral', 'escuela-infantil', 'publico', 'Plaza Canthal, 2', '30300', 'cartagena', 'Cartagena', NULL, NULL, 'Barrio Peral', 37.62464596889913, -0.9910700283944607, '637235455', 'eimperal@ayto-cartagena.es', NULL, 4, 36, 'Octubre a junio: centro abierto de 7:30 a 16:00 h, horario lectivo de 8:30 a 15:30 h, con comedor de 13:00 a 14:00 h y siesta de 14:00 a 15:30 h. Horario ampliado de 7:30 a 8:30 h y de 15:30 a 16:00 h. En julio, de 7:30 a 15:00 h', ARRAY['comedor','cocina-propia','horario-ampliado','servicio-madrugadores']::text[], 'La Escuela Infantil Municipal Barrio Peral, en Plaza Canthal, 2, forma parte de la red de escuelas infantiles gestionadas por el Ayuntamiento de Cartagena. Atiende a niños de 4 meses a 3 años con comedor propio y horario ampliado hasta las 16:00 h. Las 1.010 plazas de la red municipal son gratuitas, aunque conviene informarse sobre plazos de matrícula con antelación.', 'La Escuela Infantil Municipal Barrio Peral es uno de los once centros que integran la red de escuelas infantiles de titularidad pública gestionada por la Concejalía de Educación del Ayuntamiento de Cartagena, con sede en Plaza Canthal, 2, en el propio barrio que da nombre al centro.

Como el resto de la red municipal, atiende el primer ciclo de educación infantil: niños de 4 meses a 3 años. El horario habitual, de octubre a junio, es de 7:30 a 16:00 h, con jornada lectiva de 8:30 a 15:30 h, comedor de 13:00 a 14:00 h elaborado en el propio centro y siesta de 14:00 a 15:30 h. Quienes lo necesiten pueden ampliar el horario de 7:30 a 8:30 h por la mañana y de 15:30 a 16:00 h por la tarde. En julio el horario se reduce (7:30 a 15:00 h) y en septiembre se aplica un periodo de adaptación con horario flexible.

Las plazas de las escuelas infantiles municipales de Cartagena son gratuitas: la red ofertó 1.010 plazas gratuitas para el curso 2026-2027 en sus centros. La demanda suele ser alta, por lo que conviene informarse con antelación sobre los plazos de matrícula, gestionados de forma centralizada por la Concejalía de Educación (C/ San Miguel, 8).', '{}'::text[], '[{"question":"¿Dónde está ubicada la Escuela Infantil Municipal Barrio Peral?","answer":"El centro se encuentra en Plaza Canthal, 2, en el barrio de Barrio Peral, Cartagena."},{"question":"¿Qué edades atiende esta escuela infantil municipal?","answer":"Atiende a niños de 4 meses a 3 años, como el resto de la red de escuelas infantiles municipales de Cartagena."},{"question":"¿Es un centro público o privado?","answer":"Es un centro público, gestionado por la Concejalía de Educación del Ayuntamiento de Cartagena."},{"question":"¿Tiene comedor y horario ampliado?","answer":"Sí. El centro elabora la comida propia y ofrece horario ampliado de 7:30 a 8:30 h y de 15:30 a 16:00 h, además del horario lectivo de 8:30 a 15:30 h."},{"question":"¿Las plazas son gratuitas?","answer":"Sí, las plazas de la red de escuelas infantiles municipales de Cartagena son gratuitas. Para el curso 2026-2027 se ofertaron 1.010 plazas gratuitas en el conjunto de la red."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 637235455 o escribir a eimperal@ayto-cartagena.es."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://educacion.cartagena.es/escuelas_infantiles.asp', ARRAY['https://mapaescolar.murciaeduca.es/mapaescolar-api/api/centros','https://educacion.cartagena.es/detalle_centros.asp?idCentro=2082','https://educacion.cartagena.es/escuelas_infantiles_horario.asp','https://educacion.cartagena.es/escuelas_infantiles_matriculacion.asp']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
